package bg.tuvarna.sit.project.ps.internshipmanagement.service;
import bg.tuvarna.sit.project.ps.internshipmanagement.entity.User;import bg.tuvarna.sit.project.ps.internshipmanagement.exception.*;import bg.tuvarna.sit.project.ps.internshipmanagement.repository.UserRepository;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;
@Service public class CurrentUserService{private final UserRepository users;public CurrentUserService(UserRepository u){users=u;}public User get(){Object d=SecurityContextHolder.getContext().getAuthentication()==null?null:SecurityContextHolder.getContext().getAuthentication().getDetails();if(!(d instanceof Long id))throw new ForbiddenActionException("Authentication required");return users.findById(id).orElseThrow(()->new ResourceNotFoundException("Current user not found"));}}
